const crypto = require('crypto');
const body = $input.first().json.body || $input.first().json;
const sig = body.signature || {};
const timestamp = String(sig.timestamp || '');
const token = String(sig.token || '');
const signature = String(sig.signature || '');
const signingKey = $env.MAILGUN_WEBHOOK_SIGNING_KEY || '';
if (!timestamp || !token || !signature || !signingKey) {
  return [{ json: { valid: false, reason: 'missing_signature_fields' } }];
}
const hmac = crypto.createHmac('sha256', signingKey);
hmac.update(timestamp + token);
const digest = hmac.digest('hex');
const valid = digest === signature;
return [{ json: { valid, body, reason: valid ? 'ok' : 'hmac_mismatch' } }];

const crypto = require('crypto');

function stripIpFields(obj) {
  if (obj == null || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(stripIpFields);
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    const lk = k.toLowerCase();
    if (lk === 'ip' || lk.endsWith('-ip') || lk.includes('client-ip') || lk === 'sender-ip') continue;
    out[k] = stripIpFields(v);
  }
  return out;
}

const envelope = $('Verify Mailgun Signature').first().json.body;
const eventData = envelope['event-data'] || envelope.event_data || {};
const rawEvent = (eventData.event || envelope.event || '').toLowerCase();

const eventMap = {
  delivered: 'delivered',
  opened: 'opened',
  clicked: 'clicked',
  permanent_fail: 'bounced',
  failed: 'bounced',
  complained: 'complained',
  unsubscribed: 'unsubscribed',
};
const event = eventMap[rawEvent] || rawEvent;

const recipient = (eventData.recipient || envelope.recipient || '').toLowerCase();
const url = eventData.url || null;
const clientInfo = eventData['client-info'] || eventData.client_info || {};
const client_name = clientInfo['client-name'] || clientInfo.client_name || clientInfo['user-agent'] || null;
const device_type = clientInfo['device-type'] || clientInfo.device_type || null;
const occurred_at = eventData.timestamp
  ? new Date(Number(eventData.timestamp) * 1000).toISOString()
  : new Date().toISOString();

const userVars = eventData['user-variables'] || eventData.user_variables || {};
const messageHeaders = eventData.message?.headers || {};
let message_id = messageHeaders['message-id'] || messageHeaders['Message-Id'] || eventData.message?.headers?.['message-id'] || null;
if (!message_id && eventData.storage && eventData.storage.url) {
  message_id = eventData.id || null;
}

const state_id_hint = userVars.state_id || userVars['v:state_id'] || null;
const lead_id_hint = userVars.lead_id || userVars['v:lead_id'] || null;
const campaign = userVars.campaign || eventData.tags?.[0] || userVars.tag || null;

const sanitized = stripIpFields(envelope);

return [{
  json: {
    event,
    raw_event: rawEvent,
    recipient,
    url,
    client_name,
    device_type,
    occurred_at,
    message_id,
    state_id_hint,
    lead_id_hint,
    campaign,
    raw: sanitized,
    is_bot: false,
    needs_bot_check: event === 'opened' || event === 'clicked',
  }
}];

const evt = $('Normalize Event').first().json;
const send = $input.first().json || {};
let is_bot = false;

const client = (evt.client_name || '').toLowerCase();
const appleProxy = /apple|mpp|proxy|icloud|macos|iphone|ipad/.test(client);

if (evt.event === 'opened') {
  if (appleProxy) {
    is_bot = true;
  } else if (send.delivered_at) {
    const deliveredMs = new Date(send.delivered_at).getTime();
    const openMs = new Date(evt.occurred_at).getTime();
    if (openMs - deliveredMs < 60 * 1000) {
      is_bot = true;
    }
  }
}

if (evt.event === 'clicked' && send.delivered_at) {
  const deliveredMs = new Date(send.delivered_at).getTime();
  const clickMs = new Date(evt.occurred_at).getTime();
  if (clickMs - deliveredMs < 30 * 1000) {
    // scanner clicking all links at once shortly after delivery
    is_bot = true;
  }
}

return [{
  json: {
    ...evt,
    send_id: send.send_id || null,
    campaign: evt.campaign || send.campaign || null,
    lead_id: send.lead_id || evt.lead_id_hint || null,
    state_id: send.state_id || evt.state_id_hint || null,
    is_bot,
  }
}];

