SET search_path TO hermes_outreach;
INSERT INTO outreach_events (send_id, campaign, event, recipient, url, client_name, device_type, is_bot, occurred_at, raw)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::timestamptz, $10::jsonb)
ON CONFLICT (send_id, event, recipient, occurred_at) DO NOTHING
RETURNING id;

SET search_path TO hermes_outreach;
INSERT INTO suppression (email, reason, campaign)
VALUES ($1, $2, $3)
ON CONFLICT (lower(email)) DO NOTHING;

