const msg = $input.first().json;
const from = (msg.from?.value?.[0]?.address || msg.from || '').toString().toLowerCase();
const inReplyTo = (msg.inReplyTo || msg.headers?.['in-reply-to'] || '').toString();
const references = (msg.references || msg.headers?.references || '').toString();
const subject = (msg.subject || '').toString();
return [{
  json: {
    sender_email: from,
    in_reply_to: inReplyTo,
    references,
    subject,
    message_id: msg.messageId || msg.headers?.['message-id'] || null,
  }
}];

