UPDATE outreach_state
SET status = 'replied', next_send_at = NULL, updated_at = now()
WHERE id = $1
RETURNING id, lead_id, campaign;

SET search_path TO hermes_outreach;
INSERT INTO suppression (email, reason, campaign)
SELECT lower(l.email), 'replied', l.campaign
FROM leads l
WHERE l.id = $1
ON CONFLICT (lower(email)) DO NOTHING;
